CREATE PROCEDURE dbo.DeleteSjJournalAtomic @JournalIdNo int AS BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF NOT EXISTS(SELECT 1 FROM dbo.SalesJournal WHERE IdNo=@JournalIdNo) RETURN 1;IF EXISTS(SELECT 1 FROM dbo.SalesJournal WHERE IdNo=@JournalIdNo AND Posted=1) THROW 51431,'Posted sales journals cannot be deleted.',1;IF EXISTS(SELECT 1 FROM dbo.SalesJournalItem i JOIN dbo.Reconciled r ON r.JournalCode='SJ' AND r.JournalItemIdNo=i.IdNo WHERE i.JournalIdNo=@JournalIdNo) THROW 51432,'Reconciled sales journals cannot be deleted.',1;BEGIN TRAN;BEGIN TRY DELETE FROM dbo.SalesDeposit WHERE SalesJournalIdNo=@JournalIdNo;DELETE FROM dbo.SalesJournalItem WHERE JournalIdNo=@JournalIdNo;DELETE FROM dbo.SalesJournal WHERE IdNo=@JournalIdNo;COMMIT;END TRY BEGIN CATCH IF XACT_STATE()<>0 ROLLBACK;THROW;END CATCH END;
GO
